mapper.select:

WHERE fcv.farm_id=#{farmId} AND fcv.crop_id=#{cropId}
AND fcv.active_yn='Y'
ORDER BY fcv.display_order, cv.name, fcv.id

mapper.update:
UPDATE farm_crop_variety SET crop_id=#{cropId}, display_order=#{displayOrder}, active_yn=#{activeYn},
    updated_by=#{userId}, updated_at=#{now}
WHERE farm_id=#{farmId} AND variety_id=#{varietyId}

UPDATE crop_season SET crop_id=#{season.cropId}, variety_id=#{season.varietyId}, name=#{season.name},
    start_date=#{season.startDate}, end_date=#{season.endDate}, updated_by=#{userId}, updated_at=#{now}
WHERE farm_id=#{season.farmId} AND id=#{season.id} AND deleted_at IS NULL

UPDATE crop_season
SET crop_id=#{newCropId}, variety_id=#{newVarietyId}, updated_by=#{userId}, updated_at=#{now}
WHERE farm_id=#{farmId}
  AND crop_id=#{oldCropId}
  AND variety_id=#{oldVarietyId}
  AND status='ACTIVE'
  AND deleted_at IS NULL

UPDATE crop_season
SET crop_id=#{newCropId}, updated_by=#{userId}, updated_at=#{now}
WHERE farm_id=#{farmId}
  AND crop_id=#{oldCropId}
  AND variety_id IS NULL
  AND status='ACTIVE'
  AND deleted_at IS NULL

UPDATE crop_season
SET variety_id=#{newVarietyId}, updated_by=#{userId}, updated_at=#{now}
WHERE farm_id=#{farmId}
  AND crop_id=#{cropId}
  AND variety_id=#{oldVarietyId}
  AND status='ACTIVE'
  AND deleted_at IS NULL
